500	    /**
501	     * Counts the existing owners whose {@code registrationDate} equals the given day. Shared by the
502	     * hard daily create limit ({@link #rejectDailyRegistrationLimit(LocalDate)}) and the soft
503	     * {@code bulkSignupWarning} flag ({@link #bulkSignupWarning(LocalDate)}) so both accumulate a
504	     * day's owners identically.
505	     *
506	     * @param date the registration date to count owners for
507	     * @return the number of existing owners registered on that day
508	     */
509	    private long ownersRegisteredOn(LocalDate date) {
510	        return this.clinicService.findAllOwners().stream()
511	            .filter(owner -> date.equals(owner.getRegistrationDate()))
512	            .count();
513	    }
514	
515	    /**
516	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
517	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
518	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
519	     */
520	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
521	
522	    /**
523	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
524	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
525	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
526	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
527	     * without a registration date, such as seed data) is never flagged.
528	     *
529	     * @param date the owner's registration date (the day it was created), or {@code null}
530	     * @return {@code true} if the day already holds more than the warning threshold of owners
531	     */
532	    private boolean bulkSignupWarning(LocalDate date) {
533	        if (date == null) {
534	            return false;
535	        }
536	        return ownersRegisteredOn(date) > BULK_SIGNUP_WARNING_THRESHOLD;
537	    }
